  function vnoise3(x, y, z, seed) {
    var ix = Math.floor(x), iy = Math.floor(y), iz = Math.floor(z);
    var fx = x - ix, fy = y - iy, fz = z - iz;
    var ux = fx * fx * (3 - 2 * fx), uy = fy * fy * (3 - 2 * fy), uz = fz * fz * (3 - 2 * fz);
    function h(i, j, k) { var n = i * 127.1 + j * 311.7 + k * 74.7 + seed * 269.5, s = Math.sin(n) * 43758.5453; return s - Math.floor(s); }
    var c000 = h(ix, iy, iz), c100 = h(ix + 1, iy, iz), c010 = h(ix, iy + 1, iz), c110 = h(ix + 1, iy + 1, iz);
    var c001 = h(ix, iy, iz + 1), c101 = h(ix + 1, iy, iz + 1), c011 = h(ix, iy + 1, iz + 1), c111 = h(ix + 1, iy + 1, iz + 1);
    var x00 = c000 + (c100 - c000) * ux, x10 = c010 + (c110 - c010) * ux, x01 = c001 + (c101 - c001) * ux, x11 = c011 + (c111 - c011) * ux;
    var y0 = x00 + (x10 - x00) * uy, y1 = x01 + (x11 - x01) * uy;
    return y0 + (y1 - y0) * uz;
  }
