        if (cfg.action === 'set-variable') { App.applyVariable(cfg); return; }
        if (cfg.action === 'url') { if (App.safeUrl(cfg.url)) window.open(String(cfg.url).trim(), '_blank', 'noopener,noreferrer'); return; }
